package com.darklandsmobile.grimreich.v1
import org.junit.jupiter.api.Assertions.*; import org.junit.jupiter.api.Test; import kotlin.random.Random
class RewardTableStatsTest { @Test fun `single roll returns one entry and respects weights`(){ val a=GrimBuilders.item(id="a",name="A"); val b=GrimBuilders.item(id="b",name="B"); val table=GrimBuilders.rewardTable(entries=listOf(GrimBuilders.lootEntry(a.id,90),GrimBuilders.lootEntry(b.id,10))); val mapper=LootMapper(mapOf(a.id to a,b.id to b)); assertTrue(mapper.rollReward(table,Random(2024)).isNotEmpty()) } @Test fun `statistical distribution approximates weights`(){ val a=GrimBuilders.item(id="a",name="A"); val b=GrimBuilders.item(id="b",name="B"); val table=GrimBuilders.rewardTable(entries=listOf(GrimBuilders.lootEntry(a.id,80),GrimBuilders.lootEntry(b.id,20))); val mapper=LootMapper(mapOf(a.id to a,b.id to b)); var countA=0; var countB=0; repeat(5000){ val res=mapper.rollReward(table,Random(it)); if(res.isNotEmpty()) when(res.first().first.id){ a.id->countA++; b.id->countB++ } }; val ratioA=countA.toDouble()/(countA+countB); assertTrue(ratioA in 0.75..0.85) } @Test fun `entries with zero weight are ignored`(){ val a=GrimBuilders.item(id="a",name="A"); val table=GrimBuilders.rewardTable(entries=listOf(GrimBuilders.lootEntry(a.id,0))); val mapper=LootMapper(mapOf(a.id to a)); assertTrue(mapper.rollReward(table,Random(1)).isEmpty()) } }
